function X.GetSpellReplaceWeight(sAbilityName)
    for _, spell in pairs(X['SpellsMap']) do
        if spell and spell.name == sAbilityName and spell.weight then
            return spell.weight
        end
    end

    return 1
end

function X.GetSpellHeroName(sAbilityName)
    for _, spell in pairs(X['SpellsMap']) do
        if spell and spell.name == sAbilityName and spell.owner then
            return spell.owner
        end
    end

    return nil
end

return X